import { Outlet, useOutletContext } from "@kasperrt/smolter/preact";

interface PageContext {
  canEdit: boolean;
}

export function Layout() {
  return <Outlet context={{ canEdit: true }} />;
}

export function EditStatus() {
  const context = useOutletContext<PageContext>();

  return <span>{context.canEdit ? "Editable" : "Read only"}</span>;
}
